    class BotF:
        def __init__(self):
            self.vues, self.dyn = [], []

        def add_view(self, v, message_id=None):
            # Meme garde que discord.Client.add_view.
            if not v.is_persistent():
                raise ValueError("View is not persistent")
            self.vues.append(v)

        def add_dynamic_items(self, *its):
            self.dyn.extend(its)


