    _motifs = [(c.__name__, c.__discord_ui_compiled_template__) for c in _bot.dyn]


    def qui(cid):
        n = _persist.count(cid)
        return ["vue"] * n + [nm for nm, p in _motifs if p.fullmatch(cid)]


