    check("_pin_menus_for_guild : le menu pose porte l'identite du salon, sans embed",
          U._menu_va_lire(_poses1[0])[0] == "julia" and not _poses1[0].embeds)

    # /menu
    _vrai_gui = U.get_user_identity
    U.get_user_identity = lambda uid: "julia"
