    def choisir(menu, valeur, message, channel, mode="defer"):
        COG.mode = mode
        menu.item._values = [valeur]
        itx = Itx(message=message, channel=channel, guild=GUILD_IC)
        lancer(menu.callback(itx))
        menu.item._values = []
        return itx


