    class _Journal(logging.Handler):
        def __init__(self):
            super().__init__(logging.DEBUG)
            self.lignes = []

        def emit(self, r):
            self.lignes.append((r.levelname, r.name, r.getMessage()))


    JOURNAL = _Journal()
    logging.getLogger().addHandler(JOURNAL)
