    def v2(texte_, *rangees):
        v = ui.LayoutView(timeout=None)
        c = ui.Container()
        if texte_:
            c.add_item(ui.TextDisplay(texte_))
        for r in rangees:
            ar = ui.ActionRow()
            for it in r:
                ar.add_item(it)
            c.add_item(ar)
        v.add_item(c)
        return v


    def classique(*its):
        v = ui.View(timeout=None)
        for it in its:
            v.add_item(it)
        return v


