        _idR = iter(range(10 ** 17, 10 ** 17 + 10 ** 5))

        class _MsgR:
            def __init__(self, ch, **k):
                self.id = next(_idR); self.ch = ch; self.k = dict(k)
                self.author = _tyR.SimpleNamespace(id=1, bot=True)
